const hubs=[{"id": 67, "title": "VIVIENDA Y CUIDADOS", "members": [1, 2, 3, 4, 5, 7, 10, 56, 57, 68], "decision": "Acordar prioridades de acceso y cuidado entre residentes y dar seguimiento a respuestas.", "resources": "Tiempo remunerado o disponible, información accesible y respaldo de participantes. Las inversiones locales conservan sus procedimientos de aprobación."}, {"id": 63, "title": "COMERCIO Y PROXIMIDAD", "members": [13, 14, 15, 16, 18, 28, 62, 64, 74], "decision": "Acordar entregas y condiciones comerciales con los participantes y comparar costos de distribución.", "resources": "Consentimiento de comerciantes, instalaciones y medios de transporte. Cada organización conserva las decisiones sobre sus recursos."}, {"id": 66, "title": "MOVILIDAD Y ACCESO", "members": [20, 59, 60], "decision": "Acordar ventanas operativas con transportadores y presentar ajustes de acceso y recorridos a la autoridad vial.", "resources": "Disponibilidad de flota, información de recorridos y capacidad vial. La señalización y gestión del tránsito corresponden a la autoridad competente."}, {"id": 65, "title": "TRABAJO Y SEGURIDAD", "members": [6, 8, 9, 19, 21], "decision": "Acordar condiciones de turnos y manejo de carga con trabajadores y responsables de operación.", "resources": "Representación laboral, equipos, descansos y acuerdos con empleadores. La coordinación debe contar con tiempo y protección para participar."}, {"id": 75, "title": "OPERACIÓN LOGÍSTICA", "members": [25, 26, 27, 72, 73], "decision": "Coordinar cupos y transferencias entre destinos con capacidad asignada y acuerdos de cada operador.", "resources": "Muelles, almacenamiento, presupuesto delegado y personal. Gerencia y Junta conservan las facultades establecidas sobre contratos y recursos."}, {"id": 24, "title": "RECUPERACIÓN DE ALIMENTOS", "members": [17, 23], "decision": "Acordar recepción, clasificación y entrega de alimentos aptos con donantes y receptores.", "resources": "Almacenamiento, condiciones sanitarias, personal y transporte. La disponibilidad y aptitud del alimento delimitan la operación."}, {"id": 31, "title": "RESIDUOS Y MATERIALES", "members": [22, 29, 30, 32, 33, 34, 43, 44, 61], "decision": "Coordinar separación, rutas y mantenimiento dentro de capacidades contratadas y registrar cantidades.", "resources": "Contrato, rutas, equipos y capacidad de tratamiento. La autoridad y la interventoría revisan obligaciones y resultados."}, {"id": 35, "title": "AGUA Y HUMEDAL", "members": [11, 41, 45, 58, 69], "decision": "Coordinar mantenimiento y seguimiento de agua y hábitat según las actuaciones autorizadas.", "resources": "PMA, permisos, personal técnico y capacidad de drenaje. La autoridad ambiental conserva las decisiones de su competencia."}, {"id": 37, "title": "VEGETACIÓN Y POLINIZADORES", "members": [40, 42, 52, 53, 54, 55, 71], "decision": "Proponer manejo de vegetación, recursos florales y mantenimiento con seguimiento técnico.", "resources": "Inventario, material vegetal, agua y mantenimiento. Las intervenciones requieren autorización y criterios del organismo responsable."}, {"id": 36, "title": "FAUNA Y BIENESTAR", "members": [12, 38, 39, 46, 47, 48, 49, 50, 51, 70], "decision": "Acordar protocolos de observación y plantear ajustes ante perturbaciones documentadas.", "resources": "Registros, profesionales y protocolos específicos. Los manejos de fauna se sujetan a las competencias de cada institución."}];
