function visibleLinks(){return links.filter(l=>mode===0?l.status==='documentada':mode===1?l.status==='documentada'||hubIds.has(l.a)&&hubIds.has(l.b):true);}
let coords=positions.map(p=>[...p.current]);
function degrees(id,ls=visibleLinks()){return {incoming:ls.filter(l=>l.b===id).length,outgoing:ls.filter(l=>l.a===id).length};}
// Constant area scale across both networks; base area keeps zero-input actors visible.
function nodeRadius(id,ls=visibleLinks()){return Math.sqrt(64+100*degrees(id,ls).incoming);}
let graphOnScreen=true;
